const recurringHolidays = [
  { date: '0501', dateName: '\uADFC\uB85C\uC790\uC758 \uB0A0' },
  { date: '1231', dateName: '\uCC3D\uB9BD\uAE30\uB150\uC77C\uB300\uD734' }
];

const baseline = $('Weekday Baseline').first().json;
const apiPayload = $('Holiday API Fetch').first()?.json ?? {};
const dbPayload = $('Holiday DB Fallback').first()?.json ?? {};

function normalizeApiItems(raw) {
  if (!raw) return [];
  return Array.isArray(raw) ? raw : [raw];
}

const apiItems = !apiPayload.error
  ? normalizeApiItems(apiPayload.response?.body?.items?.item)
  : [];
const apiMatch = apiItems.find((item) => String(item?.locdate ?? '') === String(baseline.todayInt));
const customMatch = recurringHolidays.find((item) => item.date === baseline.todayMMDD);
const dbFound = !dbPayload.error && [true, 1, '1', 'true'].includes(dbPayload.found_in_db);

let isHoliday = !!baseline.DefaultIsHoliday;
let holidayName = baseline.DefaultHolidayName || (isHoliday ? '\uC8FC\uB9D0' : '\uD3C9\uC77C');
let holidayLookupSource = isHoliday ? 'default-weekend' : 'default-weekday';

if (apiMatch) {
  isHoliday = true;
  holidayName = String(apiMatch.dateName || '\uACF5\uD734\uC77C');
  holidayLookupSource = 'api';
} else if (customMatch) {
  isHoliday = true;
  holidayName = customMatch.dateName;
  holidayLookupSource = 'custom';
} else if (dbFound) {
  isHoliday = true;
  holidayName = String(dbPayload.holiday_name || '\uACF5\uD734\uC77C');
  holidayLookupSource = dbPayload.source_type ? `db:${dbPayload.source_type}` : 'db';
}

return [{
  json: {
    check_date: baseline.todayInt,
    is_holiday: isHoliday,
    holiday_name: holidayName,
    is_weekend: !!baseline.IsWeekend,
    weekday_name: baseline.WeekdayName,
    holiday_lookup_source: holidayLookupSource,
    holiday_lookup_failed: Boolean(apiPayload.error) && Boolean(dbPayload.error),
    api_error: apiPayload.error?.message || apiPayload.error || '',
    db_error: dbPayload.error || ''
  }
}];

const issueItems = $('Backlog Fetch').all();
const vacationItems = $('TS Calendar Fetch').all();
const holidayInfo = $('Holiday Judge').first().json;
const workflowStaticData = $getWorkflowStaticData('global');

if (!workflowStaticData.specialWindowNotified) {
  workflowStaticData.specialWindowNotified = {};
}

const specialWindowNotified = workflowStaticData.specialWindowNotified;

const K = {
  status: '\uC0C1\uD0DC',
  registered: '\uB4F1\uB85D',
  issueType: '\uC774\uC288 \uD0C0\uC785',
  taskName: '\uC5C5\uBB34 \uC774\uB984',
  title: '\uC81C\uBAA9',
  suggestion: '\uC81C\uC548',
  bug: '\uBC84\uADF8',
  inquiry: '\uBB38\uC758',
  noTitle: '\uC81C\uBAA9 \uC5C6\uC74C',
  noType: '\uC720\uD615 \uC5C6\uC74C',
  none: '\uC5C6\uC74C',
  holiday: '\uACF5\uD734\uC77C',
  noneHoliday: '\uD574\uB2F9 \uC5C6\uC74C',
  vacation: '\uD734\uAC00',
  annual: '\uC5F0\uCC28',
  half: '\uBC18\uCC28',
  halfAm: '\uC624\uC804\uBC18\uCC28',
  halfPm: '\uC624\uD6C4\uBC18\uCC28',
  official: '\uACF5\uAC00',
  offday: '\uD734\uC77C',
  holidayWord: '\uACF5\uD734\uC77C',
  weekendText: '\uC8FC\uB9D0 09:00 1\uD68C \uC54C\uB9BC',
  holidayText: '\uACF5\uD734\uC77C 09:00 1\uD68C \uC54C\uB9BC',
  allVacationText: '\uD3C9\uC77C \uC804\uC6D0 \uD734\uAC00 09:00 1\uD68C \uC54C\uB9BC',
  businessText: '\uD3C9\uC77C \uC5C5\uBB34\uC2DC\uAC04 30\uBD84 \uC8FC\uAE30 \uC54C\uB9BC'
};

const now = new Date();
const todayKST = new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Asia/Seoul'
}).format(now);
const dateString = new Intl.DateTimeFormat('ko-KR', {
  timeZone: 'Asia/Seoul',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  weekday: 'short'
}).format(now);
const weekdayName = new Intl.DateTimeFormat('en-US', {
  timeZone: 'Asia/Seoul',
  weekday: 'short'
}).format(now);
const hour = parseInt(new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Asia/Seoul',
  hour: '2-digit',
  hour12: false
}).format(now), 10);
const minute = parseInt(new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Asia/Seoul',
  minute: '2-digit'
}).format(now), 10);
const minutesOfDay = (hour * 60) + minute;
const isNineAm = hour === 9 && minute === 0;

const isHoliday = !!holidayInfo.is_holiday;
const isWeekend = ['Sat', 'Sun'].includes(weekdayName);
const isWeekday = !isWeekend && !isHoliday;
const isBusinessHours = isWeekday && minutesOfDay >= 480 && minutesOfDay <= 1080;
const isWeekendOrHoliday = isWeekend || isHoliday;

const allUsers = [
  { name: '\uC870\uD604\uC7AC', slackId: 'U07K2APTEVD', email: 'jyi30@vms-solutions.com' },
  { name: '\uAE40\uBBFC\uC601', slackId: 'U07EEDTJZQE', email: 'mykim@vms-solutions.com' },
  { name: '\uAE40\uC9C4\uC6B1', slackId: 'U05DQA2L7JT', email: 'jwkim@vms-solutions.com' }
];

const cleanStr = (str) => (str ?? '').toString().normalize('NFC').trim();
const norm = (str) => cleanStr(str).replace(/\s+/g, '').toLowerCase();

function findPropertyKey(props, exactName, partialName) {
  if (!props || typeof props !== 'object') return null;
  if (props[exactName]) return exactName;

  const exactNormalized = Object.keys(props).find((k) => norm(k) === norm(exactName));
  if (exactNormalized) return exactNormalized;

  const partialNormalized = Object.keys(props).find((k) => norm(k).includes(norm(partialName)));
  return partialNormalized || null;
}

function notionPropToString(prop) {
  if (!prop || typeof prop !== 'object') return '';

  switch (prop.type) {
    case 'status':
      return cleanStr(prop.status?.name);
    case 'select':
      return cleanStr(prop.select?.name);
    case 'title':
      return cleanStr((prop.title || []).map((t) => t.plain_text || t.text?.content || '').join(''));
    case 'rich_text':
      return cleanStr((prop.rich_text || []).map((t) => t.plain_text || t.text?.content || '').join(''));
    case 'people':
      return cleanStr((prop.people || []).map((p) => p.name || p.person?.email || '').join(', '));
    case 'date':
      return cleanStr(prop.date?.start);
    case 'checkbox':
      return String(!!prop.checkbox);
    case 'number':
      return prop.number == null ? '' : String(prop.number);
    case 'formula':
      if (!prop.formula) return '';
      if (prop.formula.type === 'string') return cleanStr(prop.formula.string);
      if (prop.formula.type === 'number') return prop.formula.number == null ? '' : String(prop.formula.number);
      if (prop.formula.type === 'boolean') return String(!!prop.formula.boolean);
      if (prop.formula.type === 'date') return cleanStr(prop.formula.date?.start);
      return '';
    default:
      return '';
  }
}

function flatValueToString(value) {
  if (value == null) return '';

  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    return cleanStr(value);
  }

  if (Array.isArray(value)) {
    return cleanStr(value.map((v) => flatValueToString(v)).filter(Boolean).join(', '));
  }

  if (typeof value === 'object') {
    if ('name' in value) return cleanStr(value.name);
    if ('plain_text' in value) return cleanStr(value.plain_text);
    if ('start' in value) return cleanStr(value.start);
    if ('end' in value) return cleanStr(value.end);
  }

  return '';
}

function getFieldValue(page, candidateNames) {
  if (page.properties && typeof page.properties === 'object') {
    for (const name of candidateNames) {
      const propKey = findPropertyKey(page.properties, name, name);
      if (propKey) {
        const value = notionPropToString(page.properties[propKey]);
        if (value) return value;
      }
    }
  }

  for (const name of candidateNames) {
    const flatKey = findPropertyKey(page, name, name);
    if (flatKey) {
      const value = flatValueToString(page[flatKey]);
      if (value) return value;
    }
  }

  return '';
}

function getStatus(page) {
  return getFieldValue(page, [K.status, 'Status']);
}

function getIssueType(page) {
  return getFieldValue(page, [K.issueType, 'Issue Type', 'Type']);
}

function getTitle(page) {
  return getFieldValue(page, [K.taskName, 'Name', 'title', K.title]);
}

function getUrl(page) {
  return cleanStr(page.url || page.URL || page.public_url || '');
}

function collectStrings(value, result = [], depth = 0) {
  if (depth > 10 || value == null) return result;

  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    result.push(String(value));
    return result;
  }

  if (Array.isArray(value)) {
    for (const v of value) collectStrings(v, result, depth + 1);
    return result;
  }

  if (typeof value === 'object') {
    for (const v of Object.values(value)) collectStrings(v, result, depth + 1);
  }

  return result;
}

function itemToSearchText(item) {
  return collectStrings(item?.json ?? item).join(' ');
}

function isVacationText(text) {
  const t = norm(text);
  return [
    K.vacation, K.annual, K.half, K.halfAm, K.halfPm, K.official, K.offday, K.holidayWord,
    'sabbatical', 'leave', 'vacation', 'pto', 'dayoff', 'off'
  ].some((keyword) => t.includes(norm(keyword)));
}

function extractAllYmds(text) {
  return String(text ?? '').match(/\d{4}-\d{2}-\d{2}/g) || [];
}

function extractYmd(str) {
  const match = String(str ?? '').match(/\d{4}-\d{2}-\d{2}/);
  return match ? match[0] : '';
}

function extractDateRanges(item) {
  const obj = item?.json ?? item;
  const ranges = [];
  const seen = new Set();

  function pushRange(key, start, end) {
    const s = extractYmd(start);
    const e = extractYmd(end || start);
    if (!s) return;

    const uniq = key + '|' + s + '|' + e;
    if (seen.has(uniq)) return;
    seen.add(uniq);
    ranges.push({ key, start: s, end: e || s });
  }

  function walk(value, path, depth) {
    if (depth > 8 || value == null) return;

    if (typeof value === 'string') {
      const ymds = extractAllYmds(value);
      if (ymds.length === 1) pushRange(path, ymds[0], ymds[0]);
      else if (ymds.length >= 2) pushRange(path, ymds[0], ymds[1]);
      return;
    }

    if (typeof value === 'number' || typeof value === 'boolean') return;

    if (Array.isArray(value)) {
      value.forEach((v, idx) => walk(v, path + '[' + idx + ']', depth + 1));
      return;
    }

    if (typeof value === 'object') {
      if ('start' in value && extractYmd(value.start)) {
        pushRange(path + '.startEnd', value.start, value.end || value.start);
      }

      if ('date' in value && value.date && typeof value.date === 'object' && extractYmd(value.date.start)) {
        pushRange(path + '.date', value.date.start, value.date.end || value.date.start);
      }

      if (
        'formula' in value &&
        value.formula &&
        typeof value.formula === 'object' &&
        value.formula.type === 'date' &&
        value.formula.date &&
        extractYmd(value.formula.date.start)
      ) {
        pushRange(path + '.formula.date', value.formula.date.start, value.formula.date.end || value.formula.date.start);
      }

      for (const [key, nested] of Object.entries(value)) {
        walk(nested, path + '.' + key, depth + 1);
      }
    }
  }

  walk(obj, 'root', 0);
  return ranges;
}

function isTodayIncluded(start, end, today) {
  if (!start) return false;
  const realEnd = end || start;
  return start <= today && today <= realEnd;
}

const todayVacationItems = vacationItems.filter((item) => {
  const text = itemToSearchText(item);
  if (!isVacationText(text)) return false;

  const ranges = extractDateRanges(item);
  if (ranges.length === 0) return false;

  return ranges.some((range) => isTodayIncluded(range.start, range.end, todayKST));
});

const vacationUsers = allUsers.filter((user) => {
  return todayVacationItems.some((item) => {
    const text = itemToSearchText(item);
    return norm(text).includes(norm(user.name)) || norm(text).includes(norm(user.email));
  });
});

const vacationUserEmails = new Set(vacationUsers.map((user) => user.email));
const activeUsers = allUsers.filter((user) => !vacationUserEmails.has(user.email));
const isAllUsersOnVacation = activeUsers.length === 0;

const pages = issueItems
  .map((item) => item?.json)
  .filter((page) => page && typeof page === 'object' && page.properties && typeof page.properties === 'object');

const registeredIssues = pages.filter((page) => {
  const statusName = getStatus(page);
  const typeName = getIssueType(page);
  const isRegistered = norm(statusName) === norm(K.registered);
  const isTargetType = [K.suggestion, K.bug, K.inquiry].some((t) => norm(typeName) === norm(t));
  return isRegistered && isTargetType;
});

const currentRegisteredIds = new Set(registeredIssues.map((page) => page.id));
for (const issueId of Object.keys(specialWindowNotified)) {
  if (!currentRegisteredIds.has(issueId)) {
    delete specialWindowNotified[issueId];
  }
}

let alertMode = '';
let alertModeText = '';
let targetIssues = [];
let targetUsers = activeUsers;

if (isWeekendOrHoliday) {
  if (!isNineAm) {
    return [];
  }

  alertMode = isHoliday ? 'holiday_once_0900' : 'weekend_once_0900';
  alertModeText = isHoliday ? K.holidayText : K.weekendText;
  targetUsers = allUsers;
  targetIssues = registeredIssues.filter((page) => !specialWindowNotified[page.id]);
} else if (isWeekday && isAllUsersOnVacation) {
  if (!isNineAm) {
    return [];
  }

  alertMode = 'weekday_all_vacation_once_0900';
  alertModeText = K.allVacationText;
  targetUsers = allUsers;
  targetIssues = registeredIssues.filter((page) => !specialWindowNotified[page.id]);
} else if (isBusinessHours) {
  alertMode = 'business_hours_repeat';
  alertModeText = K.businessText;
  targetUsers = activeUsers;
  targetIssues = registeredIssues;
} else {
  return [];
}

if (targetIssues.length === 0) {
  return [];
}

if (alertMode !== 'business_hours_repeat') {
  for (const page of targetIssues) {
    specialWindowNotified[page.id] = {
      notifiedAt: new Date().toISOString(),
      title: getTitle(page),
      date: todayKST,
      mode: alertMode
    };
  }
}

let teamsText = 'support target';
let teamsEntities = [];
if (targetUsers.length > 0) {
  teamsText = targetUsers.map((user) => '<at>' + user.name + '</at>').join(', ');
  teamsEntities = targetUsers.map((user) => ({
    type: 'mention',
    text: '<at>' + user.name + '</at>',
    mentioned: { id: user.email, name: user.name }
  }));
}

const issuesList = targetIssues.map((page, index) => {
  const title = getTitle(page) || K.noTitle;
  const type = getIssueType(page) || K.noType;
  const url = getUrl(page);
  return url
    ? (index + 1) + '. [' + type + '] ' + title + ' ([\uBC14\uB85C\uAC00\uAE30](' + url + '))'
    : (index + 1) + '. [' + type + '] ' + title;
});

const holidayText = isHoliday ? holidayInfo.holiday_name || K.holiday : K.noneHoliday;
const vacationUsersText = vacationUsers.length > 0 ? vacationUsers.map((user) => user.name).join(', ') : K.none;
const targetUsersText = targetUsers.length > 0 ? targetUsers.map((user) => user.name).join(', ') : K.none;

return [{
  json: {
    teamsText,
    teamsEntities,
    issuesContent: issuesList.join('\n\n'),
    issueCount: targetIssues.length,
    date: dateString,
    holidayText,
    alertMode,
    alertModeText,
    vacationUsersText,
    activeUsersText: targetUsersText,
    isBusinessHours,
    isHoliday,
    isWeekend,
    isAllUsersOnVacation,
    debug: {
      todayKST,
      time: String(hour).padStart(2, '0') + ':' + String(minute).padStart(2, '0'),
      registeredIssueCount: registeredIssues.length,
      notifiedIssueCount: targetIssues.length,
      targetUsers: targetUsers.map((user) => ({ name: user.name, email: user.email })),
      vacationUsers: vacationUsers.map((user) => ({ name: user.name, email: user.email }))
    }
  }
}];

